[2] "nopii_canv_export_20260810-20260831_c1_complete_closed.xlsx"
[3] "nopii_canv_export_20260810-20260831_c1_partial_closed.xlsx" 
[4] "nopii_canv_export_20260829_20260831_c2_complete_closed.xlsx"
[5] "nopii_canv_export_20260829_20260831_c2_partial_closed.xlsx" 
```


:::
:::




Every column any version can carry is mapped; the ones a given version lacks
are simply absent for its rows. The canvasser's street-address columns, which
`c3` carries, must be empty, as for the survey.




::: {.cell}

```{.r .cell-code}
col_map_canv_revised <- c(
  submitted_at      = "Time",
  canvasser_address  = "For Canvasser: Enter the ZIP code of the place you are canvassing  (Address)",
  canvasser_address2 = "For Canvasser: Enter the ZIP code of the place you are canvassing  (Address2)",
  canvasser_city     = "For Canvasser: Enter the ZIP code of the place you are canvassing  (City)",
  canvasser_state    = "For Canvasser: Enter the ZIP code of the place you are canvassing  (State)",
  canvasser_zip     = col_map_canv[["canvasser_zip"]],
  canvass_mode      = col_map_canv[["canvass_mode"]],
  responded         = col_map_canv[["responded"]],
  screener          = "1. Do you need care or is there someone in your life you help take care of – a kid, a parent, a grandparent, or anyone else?",
  hard_text         = "2. What’s been hard about that?",
  continue_full     = col_map_canv[["continue_full"]],
  battery,
  respondent_id     = "Unique ID"
)
always_present <- c("submitted_at", "screener", "hard_text", "respondent_id")

canvassing_revised <- canvassing_revised_files |>
  map(\(path) {
    read_excel(path, col_types = "text") |>
      rename(any_of(timestamp_aliases)) |>
      mutate(across(everything(), \(x) na_if(str_trim(normalize_punctuation(x)), ""))) |>
      rename_validated(col_map_canv_revised,
                       optional = setdiff(names(col_map_canv_revised), always_present)) |>
      mutate(delivery = basename(path))
  }) |>
  bind_rows() |>
  mutate(
    form_version    = str_to_lower(str_extract(delivery, regex("c\\d+", ignore_case = TRUE))),
    response_status = str_extract(delivery, "complete|partial")
  )

pii_cols <- intersect(c("canvasser_address", "canvasser_address2"), names(canvassing_revised))
if (any(!is.na(as.matrix(canvassing_revised[pii_cols])))) {
  stop("Canvasser address fields are not empty — flag to the team before proceeding.")
}
canvassing_revised <- select(canvassing_revised, -any_of(c(pii_cols, "canvasser_city", "canvasser_state")))
